def calculate_lightning_distance(seconds, unit='km'):
    speed_of_sound_mps = 343
    distance_meters = seconds * speed_of_sound_mps
    if unit == 'km':
        return distance_meters / 1000
    elif unit == 'miles':
        return distance_meters / 1609.34
    return distance_meters

